steps.script:
  
# Use the cloud redirect to a CRAN mirror
old.repos <- getOption("repos") 
on.exit(options(repos = old.repos)) #this resets the repos option when the function exits 
new.repos <- old.repos 
new.repos["CRAN"] <- "http://cran.rstudio.com" #set your favorite CRAN Mirror here 
options(repos = new.repos) 

# Install the package if it is not loadable
x <- as.character(substitute("mcr"))
if(isTRUE(x %in% .packages(all.available=TRUE))) { 
 loaded<-eval(parse(text=paste("require(", x, ")", sep=""))) 
 } else { 
 install.packages(x, quiet=T, lib=rlib) 
 loaded<-eval(parse(text=paste("require(", x, ")", sep=""))) 
}
if(loaded==F) { 
 update.packages(ask=F, instlib=rlib)
 install.packages(x, quiet=T, lib=rlib) 
 loaded<-eval(parse(text=paste("require(", x, ")", sep=""))) 
}
# By now, the package should have been installed one way or another.  Load the package
library("mcr")

statsdirect.image <- setClass("statsdirect.image", representation(path="character"))
# Use a closure to hide the count variable in the plotter
make.statsdirect.plot <- function() {
  tempfilecount <- 0
  statsdirect.plot <- function(plotter) {
    filename <- paste ("metafile",tempfilecount,".wmf", sep="")
    path<-file.path(getwd(),filename)
    win.metafile(path)
    plotter()
    suppressWarnings(dev.off())
    tempfilecount <<- tempfilecount + 1
    statsdirect.image(path=path)
  }
}
statsdirect.plot <- make.statsdirect.plot()

statsdirect.fail <- function(s) {
  cat(s)
}

statsdirect.mkname <- function(prefix, suffix) {
  if (is.null(prefix)) {
    suffix
  } else {
    paste0(prefix,"$",suffix)
  }
}

return.atom.to.statsdirect <- function(result, op, prefix) {
  outs<-c("start~names",prefix,"start~data",as.character(result))
#  outs<-c(outs,"start~names",colnames(rn),"start~data",as.character(rn),"start~titles",rn.titles)
  writeLines(outs, op)
}

return.string.to.statsdirect <- function(result, op, prefix) {
  outs<-c("start~names",prefix,"start~data",paste0('"',result,'"'))
#  outs<-c(outs,"start~names",colnames(rn),"start~data",as.character(rn),"start~titles",rn.titles)
  writeLines(outs, op)
}

return.image.to.statsdirect <- function(result, op, prefix) {
  outs<-c('start~graphics',paste0('"',statsdirect.mkname(prefix,'chart'),'"="',result@path,'"'))
  writeLines(outs, op)
}

return.item.to.statsdirect <- function(result, op, prefix) {
  t <- typeof(result)
  if (t %in% c("logical","integer","double","NULL")) {
    return.atom.to.statsdirect(result, op, prefix)
  } else if (t == "character") {
    return.string.to.statsdirect(result, op, prefix)
  } else if (t == "list") {
    return.list.to.statsdirect(result, op, prefix)
  } else if (is(result, "statsdirect.image")) {
    return.image.to.statsdirect(result, op, prefix)
  } else {
    statsdirect.fail(paste("Unknown type", t))
  }
}

return.list.to.statsdirect <- function(result, op, prefix) {
  lapply(seq_along(result),
    function(ind, list, names, op, prefix) {
      n <- if (is.null(names) || names[ind] == "") ind else names[ind]
      return.item.to.statsdirect(list[[ind]], op, statsdirect.mkname(prefix, n))
    },
    list = result,
    names = names(result),
    op = op,
    prefix = prefix)
}

return.to.statsdirect <- function(result.list) {
  op<-file("results.txt", open="wt")
  return.list.to.statsdirect(result.list, op, NULL)
  close(op)
}

alpha <- 1.0 - ci

once <- function(sd.method.name, x, xname, y, yname, human.readable.name) {
  # If we're not supposed to do anything for this method, don't.
  if (!(exists(sd.method.name) && get(sd.method.name))) {
    return()
  }
  
  # Identify the regression test, CI approach and if necessary the bootstrap CI approach from the method name
  method.reg <- NULL
  if (sd.method.name %in% c("do.deming.jackknife", "do.deming.bootstrap", "do.deming.analytical")) {
    method.reg <- "Deming"
  } else if (sd.method.name %in% c("do.wdeming.jackknife", "do.wdeming.nestedbootstrap", "do.wdeming.analytical")) {
    method.reg <- "WDeming"
  } else if (sd.method.name %in% c("do.paba", "do.paba.nestedbootstrap")) {
    method.reg <- "PaBa"
  } else if (sd.method.name %in% c("do.pabalarge", "do.pabalarge.nestedbootstrap")) {
    method.reg <- "PaBaLarge"
  }
  method.ci <- NULL
  method.bootstrap.ci <- "BCa"
  if (sd.method.name %in% c("do.wdeming.jackknife", "do.deming.jackknife")) {
    method.ci <- "jackknife"
  } else if (sd.method.name %in% c("do.deming.bootstrap")) {
    method.ci <- "bootstrap"
  } else if (sd.method.name %in% c("do.deming.analytical", "do.wdeming.analytical")) {
    method.ci <- "analytical"
  } else if (sd.method.name %in% c("do.pabalarge", "do.paba")) {
    method.ci <- NULL
  } else if (sd.method.name %in% c("do.pabalarge.nestedbootstrap", "do.paba.nestedbootstrap", "do.wdeming.nestedbootstrap")) {
    method.ci <- "nestedbootstrap"
  }
  
  model <- mcreg(x, y, error.ratio=error.ratio, alpha=alpha, method.reg=method.reg, method.ci=method.ci, method.bootstrap.ci = method.bootstrap.ci, mref.name = xname, mtest.name = yname, na.rm=TRUE)
  if (exists("returning.to.statsdirect")) {
    retval <- list()
    retval$title <- human.readable.name
    retval$slope <- model@para[2,1]
    retval$seslope <- if (is.na(model@para[2,2])) sd(model@B1) else model@para[2,2]
    retval$slopelci <- model@para[2,3]
    retval$slopeuci <- model@para[2,4]
    retval$intercept <- model@para[1,1]
    retval$seintercept <- if (is.na(model@para[1,2])) sd(model@B0) else model@para[1,2]
    retval$interceptlci <- model@para[1,3]
    retval$interceptuci <- model@para[1,4]
    retval$samples <- length(model@data[[1]])
    if (plot.testvsreference) {
      retval$testvsreference <- statsdirect.plot(function() { plot(model,x.lab=xname,y.lab=yname) } )
    }
    if (plot.bland.altman) {
      retval$difference <- statsdirect.plot(function() { plotDifference(model) } )
    }
    if (plot.residuals) {
      retval$residuals <- statsdirect.plot(function() { plotResiduals(model) } )
    }
    if (plot.bias) {
      retval$bias <- statsdirect.plot(function() { plotBias(model) } )
    }
    return (list(values=retval, model=model))
  } else {
    printSummary(model)
    getCoefficients(model)
    if (plot.testvsreference) {
      plot(model,x.lab=xname,y.lab=yname)
    }
    if (plot.bland.altman) {
      plotDifference(model)
    }
    if (plot.residuals) {
      plotResiduals(model)
    }
    if (plot.bias) {
      plotBias(model)
    }
  }
}

x <- referencedata[[1]]
y <- testdata[[1]]
xname <- names(referencedata)[1]
yname <- names(testdata)[1]

pairs <- list()
pairs$do.deming.jackknife <- once("do.deming.jackknife", x, xname, y, yname, "Deming (jackknife CI)")
pairs$do.deming.bootstrap <- once("do.deming.bootstrap", x, xname, y, yname, "Deming (bootstrap CI)")
pairs$do.deming.analytical <- once("do.deming.analytical", x, xname, y, yname, "Deming (Wald CI)")
pairs$do.wdeming.jackknife <- once("do.wdeming.jackknife", x, xname, y, yname, "Weighted Deming (jackknife CI)")
pairs$do.wdeming.nestedbootstrap <- once("do.wdeming.nestedbootstrap", x, xname, y, yname, "Weighted Deming (nested bootstrap CI)")
pairs$do.paba <- once("do.paba", x, xname, y, yname, "Passing-Bablok (bootstrap CI)")
pairs$do.paba.nestedbootstrap <- once("do.paba.nestedbootstrap", x, xname, y, yname, "Passing-Bablok (nested boostrap CI)")
pairs$do.pabalarge <- once("do.pabalarge", x, xname, y, yname, "Approximate Passing-Bablok (bootstrap CI)")
pairs$do.pabalarge.nestedbootstrap <- once("do.pabalarge.nestedbootstrap", x, xname, y, yname, "Approximate Passing-Bablok (nested boostrap CI)")

models <- lapply(pairs, function(pair) { pair[["model"]] } )
# Unnamed lists are returned to StatsDirect as arrays of results, which can then be iterated over in reports.  So the following will allow iteration over /bs methodResults/ in a report.
method.results <- unname(lapply(pairs, function(pair) { pair[["values"]] } ))
results <- list()
results$ci100 <- ci * 100.0
results$xname <- xname
results$yname <- yname
results$methodResults <- method.results
results$samples <- if (length(method.results) == 0) 0 else method.results[[1]]$samples
if (plot.modelcomparison) {
  results$comparefit <- statsdirect.plot(function() { do.call(compareFit, models) } )
}
if (exists("returning.to.statsdirect")) {
  return.to.statsdirect(results)
}
